## 🎯 Dans cette leçon

Une LED RGB contient **trois puces** : rouge (*Red*), verte (*Green*) et bleue (*Blue*). En dosant chacune en PWM, l'œil mélange les trois lumières et voit des millions de couleurs.

À la fin de cette leçon, tu sauras :

- identifier les 4 pattes et le type (cathode ou anode commune) ;
- calculer la résistance de chaque couleur ;
- mélanger les couleurs avec trois sorties PWM ;
- écrire une fonction `couleur(r, v, b)` réutilisable.

blocs.code:
// Leçon 2.4 — afficher des couleurs avec une LED RGB à cathode commune
const int ROUGE = 9, VERT = 10, BLEU = 11;   // broches PWM (~)

void couleur(int r, int v, int b) {
  analogWrite(ROUGE, r);   // 0 à 255
  analogWrite(VERT, v);
  analogWrite(BLEU, b);
}

void setup() {
  for (int p = 9; p <= 11; p++) pinMode(p, OUTPUT);
}

void loop() {
  couleur(255, 0, 0);     delay(1000);   // rouge
  couleur(0, 255, 0);     delay(1000);   // vert
  couleur(255, 120, 0);   delay(1000);   // orange
  couleur(255, 255, 255); delay(1000);   // blanc
}

// Solution du mini-défi : la température d'un LM35 (sur A0) en couleur
const int ROUGE = 9, VERT = 10, BLEU = 11;

void couleur(int r, int v, int b) {
  analogWrite(ROUGE, r); analogWrite(VERT, v); analogWrite(BLEU, b);
}

void setup() {
  for (int p = 9; p <= 11; p++) pinMode(p, OUTPUT);
}

void loop() {
  float t = analogRead(A0) * 5.0 / 1023 * 100;   // LM35 : 10 mV par °C
  if (t < 20)        couleur(0, 0, 255);           // froid : bleu
  else if (t <= 26)  couleur(0, 255, 0);           // confortable : vert
  else               couleur(255, 0, 0);           // chaud : rouge
  delay(500);
}
// Bonus dégradé de 15 à 35 °C : int r = constrain(map(t, 15, 35, 0, 255), 0, 255); couleur(r, 0, 255 - r);

